/**
 * The `int(str)` constructor.
 *
 * Python integers are arbitrary precision, so they are represented as `BigInt`
 * here.  That also gives us a free type tag: in this port a `bigint` is a
 * Python `int` and a `number` is a Python `float`, which is exactly the
 * distinction `json.encoder` branches on.
 */

import { PyConversionError } from './pyerrors.mjs';
import {
  isAsciiSpace,
  transformDecimalAndSpaceToAscii,
} from './pyunicode.mjs';

/** Underscores are legal only when flanked by ASCII digits (PEP 515). */
function stripUnderscores(text) {
  if (!text.includes('_')) return text;
  const isDigit = (ch) => ch !== undefined && ch >= '0' && ch <= '9';
  let out = '';
  let prev = '';
  for (const ch of text) {
    if (ch === '_') {
      if (!isDigit(prev)) return null;
    } else {
      if (prev === '_' && !isDigit(ch)) return null;
      out += ch;
    }
    prev = ch;
  }
  return prev === '_' ? null : out;
}

function stripAsciiSpace(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isAsciiSpace(text[start])) start += 1;
  while (end > start && isAsciiSpace(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

const DECIMAL_INT = /^[0-9]+$/;

/**
 * `int(str)` with base 10, returning a `BigInt`.
 *
 * Leading/trailing whitespace is ignored, an optional sign may precede the
 * digits with no space between them, and non-ASCII decimal digits are accepted
 * because they are folded to ASCII first.
 */
export function pyIntFromString(text) {
  const folded = transformDecimalAndSpaceToAscii(text);
  const unscored = stripUnderscores(folded);
  if (unscored === null) throw new PyConversionError('invalid literal for int()');

  let body = stripAsciiSpace(unscored);
  let negative = false;
  if (body.startsWith('+')) {
    body = body.slice(1);
  } else if (body.startsWith('-')) {
    negative = true;
    body = body.slice(1);
  }

  if (!DECIMAL_INT.test(body)) {
    throw new PyConversionError('invalid literal for int()');
  }
  const value = BigInt(body);
  return negative ? -value : value;
}

/** `int.__repr__()`. Note that `-0` collapses to `0`, as in Python. */
export function intRepr(value) {
  return value.toString();
}
