/**
 * The slices of CPython's Unicode database that the numeric constructors and
 * `repr()` depend on.
 *
 * Everything here is derived from observable behaviour: `int()`/`float()`
 * accept non-ASCII decimal digits and non-ASCII whitespace because
 * `_PyUnicode_TransformDecimalAndSpaceToASCII()` folds them down before the
 * ASCII parser ever runs, and `repr()` escapes anything that is not
 * "printable" in Python's sense.
 */

/**
 * Code points >= 127 that `Py_UNICODE_ISSPACE()` reports as whitespace.
 *
 * Note that this deliberately excludes the ASCII range: the decimal/space fold
 * only rewrites characters above 126, which is why `int('\x1c42')` fails even
 * though `'\x1c'.isspace()` is true — the ASCII parser's own notion of
 * whitespace (`Py_ISSPACE`) stops at CR.
 */
const NON_ASCII_SPACES = new Set([
  0x0085, // NEXT LINE
  0x00a0, // NO-BREAK SPACE
  0x1680, // OGHAM SPACE MARK
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, // LINE SEPARATOR
  0x2029, // PARAGRAPH SEPARATOR
  0x202f, // NARROW NO-BREAK SPACE
  0x205f, // MEDIUM MATHEMATICAL SPACE
  0x3000, // IDEOGRAPHIC SPACE
]);

/** True for the characters `Py_ISSPACE()` recognises: `\t\n\v\f\r` and space. */
export function isAsciiSpace(ch) {
  return ch === ' ' || (ch >= '\t' && ch <= '\r');
}

/** True for code points >= 127 that Python treats as whitespace. */
export function isNonAsciiSpace(codePoint) {
  return NON_ASCII_SPACES.has(codePoint);
}

const ND = /\p{Nd}/u;

/**
 * `Py_UNICODE_TODECIMAL()` — the decimal value of a code point, or -1.
 *
 * Decimal digits always appear in aligned runs of ten, so walking backwards
 * until the category stops matching yields the offset from that run's zero.
 */
export function decimalValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30;
  if (!ND.test(String.fromCodePoint(codePoint))) return -1;
  let offset = 0;
  while (offset < 9 && ND.test(String.fromCodePoint(codePoint - offset - 1))) offset += 1;
  return offset;
}

/**
 * Port of `_PyUnicode_TransformDecimalAndSpaceToASCII()`.
 *
 * Characters below 127 pass through untouched; above that, whitespace becomes
 * a plain space, decimal digits become their ASCII counterpart, and anything
 * else becomes `'?'` so the subsequent parse is guaranteed to fail.
 */
export function transformDecimalAndSpaceToAscii(text) {
  let out = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 127) {
      out += ch;
    } else if (isNonAsciiSpace(cp)) {
      out += ' ';
    } else {
      const digit = decimalValue(cp);
      out += digit < 0 ? '?' : String(digit);
    }
  }
  return out;
}

const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/**
 * `Py_UNICODE_ISPRINTABLE()` — false for the separator and "other" categories,
 * with U+0020 carved out as the one printable space.
 */
export function isPrintable(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

/**
 * Compare two strings the way CPython's `sorted()` does: by code point.
 *
 * JavaScript's `<` compares UTF-16 code units, which disagrees with Python for
 * astral characters (they sort below U+E000 instead of above it).
 */
export function codePointCompare(a, b) {
  const left = Array.from(a);
  const right = Array.from(b);
  const shared = Math.min(left.length, right.length);
  for (let i = 0; i < shared; i += 1) {
    const x = left[i].codePointAt(0);
    const y = right[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  if (left.length === right.length) return 0;
  return left.length < right.length ? -1 : 1;
}

