// Generator for the int-parse assignment: attacks int() parsing/rendering for --b.
import { writeFileSync } from 'node:fs';

const cases = [];
const seen = new Set();
function add(b, a = 'x', c = '1.5') {
  const key = JSON.stringify([a, b, c]);
  if (seen.has(key)) return;
  seen.add(key);
  cases.push(['--a', a, '--b', b, '--c', c]);
}

// ---------------------------------------------------------------- whitespace
const WS = [
  '\t', '\n', '\v', '\f', '\r', ' ',
  '', '', '', '',      // C0 separators (isspace, not Py_ISSPACE)
  '', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', '　',
  '᠎', '​', '⁠', '﻿',      // near-miss: not whitespace in py3
];

for (const w of WS) {
  add(`${w}42`);
  add(`42${w}`);
  add(`${w}42${w}`);
  add(`${w}${w}42`);
  add(`4${w}2`);            // interior -> error
  add(`${w}-42`);
  add(`-${w}42`);           // space between sign and digits -> error
  add(`${w}+42${w}`);
  add(`${w}`);              // whitespace only -> error
  add(`${w}${w}`);
  add(`4 ${w} 2`);
  add(`${w}0${w}`);
  add(`${w}1_2${w}`);
  add(`1_2${w}`);
  add(`${w}٠١${w}`);
}
// mixed whitespace soup
add(' \t\n\v\f\r42 \t\n\v\f\r');
add('  　1234   ');
add(' 42');
add(' 42');
add('42 ');
add('42 ');
add('');
add('42');
add(' 42');

// ------------------------------------------------------------------ sign forms
for (const s of ['', '+', '-', '++', '--', '+-', '-+', ' + ', '+ ', ' -']) {
  for (const d of ['0', '1', '42', '000', '007', '0007', '123456789']) add(s + d);
}
add('-0'); add('+0'); add('-00'); add('+00000'); add('-0000000000000000000');
add('- 1'); add('+ 1'); add('1-'); add('1+'); add('4-2'); add('4+2');

// ------------------------------------------------------------- leading zeros
for (const n of [1, 2, 3, 5, 10, 20, 50, 100, 300, 1000, 4299, 4300, 4301, 5000]) {
  add('0'.repeat(n) + '1');
  add('-' + '0'.repeat(n) + '1');
  add('0'.repeat(n));
  add('-' + '0'.repeat(n));
}

// --------------------------------------------------------- huge magnitudes
const digitCounts = [
  1, 2, 9, 10, 18, 19, 20, 31, 32, 63, 64, 65, 99, 100, 101, 127, 128, 129,
  200, 255, 256, 300, 512, 999, 1000, 1023, 1024, 2000, 4095, 4096,
  4297, 4298, 4299, 4300, 4301, 4302, 4303, 4310, 4400, 5000, 8600, 10000,
];
for (const n of digitCounts) {
  add('9'.repeat(n));
  add('-' + '9'.repeat(n));
  add('1' + '0'.repeat(Math.max(0, n - 1)));
  add('-1' + '0'.repeat(Math.max(0, n - 1)));
  add('+' + '1'.repeat(n));
  add(' ' + '8'.repeat(n) + ' ');
  add('0' + '7'.repeat(n));                 // leading zero + n digits
  add('0'.repeat(10) + '7'.repeat(n));      // 10 leading zeros
  let s = '';
  for (let i = 0; i < n; i++) s += String((i * 7 + 3) % 10);
  add(s);
  add('-' + s);
  // underscore-grouped huge value
  add(s.replace(/(.{3})(?=.)/g, '$1_'));
}
// powers of two / near machine boundaries
for (const p of [30, 31, 32, 52, 53, 62, 63, 64, 65, 127, 128, 256, 512, 1024]) {
  const v = (1n << BigInt(p));
  add(v.toString()); add('-' + v.toString());
  add((v - 1n).toString()); add((-(v) + 1n).toString());
  add((v + 1n).toString()); add((-v - 1n).toString());
}

// ------------------------------------------------------- PEP 515 underscores
const underscored = [
  '1_0', '1_000', '1_000_000', '10_00_0', '1_2_3_4_5_6_7_8_9_0',
  '_1', '1_', '__1', '1__', '1__0', '1___0', '_', '__', '___',
  '_1_', '+_1', '-_1', '_+1', '_-1', '+1_', '-1_', '+1_0', '-1_0',
  '0_0', '00_00', '0_1', '_0', '0_',
  ' 1_0 ', '1 _0', '1_ 0', ' _1', '1_ ', '_ 1', '1 _ 0',
  '1_0_', '_1_0', '1_,0', '1_.0', '1_e0', '1_x0', '0_x1', '0x_1',
  '1 _ 2', '1_ 2', '1 _2',
  '١_٢', '_١', '١_', '١__٢',
  '1_٢', '١_2',
  '1_0'.repeat(1), '1_' + '0'.repeat(4300), '1_' + '0'.repeat(4299),
  '１_２', '１＿２',
];
for (const u of underscored) add(u);
// underscore at every position of a 6-char digit string
const base6 = '123456';
for (let i = 0; i <= base6.length; i++) add(base6.slice(0, i) + '_' + base6.slice(i));
for (let i = 0; i <= base6.length; i++) add('-' + base6.slice(0, i) + '_' + base6.slice(i));
for (let i = 0; i <= base6.length; i++) add(base6.slice(0, i) + '__' + base6.slice(i));
for (let i = 0; i <= base6.length; i++) add(' ' + base6.slice(0, i) + '_' + base6.slice(i) + ' ');

// --------------------------------------------- every Unicode Nd code point
const ndAll = [];
for (let cp = 0x80; cp <= 0x10ffff; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  const ch = String.fromCodePoint(cp);
  if (/\p{Nd}/u.test(ch)) ndAll.push(cp);
}
for (const cp of ndAll) {
  const ch = String.fromCodePoint(cp);
  add(ch);                 // single digit -> tests decimal value directly
}
// blocks: for each run of 10 starting at a "zero", build a 0..9 string
const runs = [];
for (let i = 0; i < ndAll.length; i++) {
  if (i === 0 || ndAll[i] !== ndAll[i - 1] + 1) runs.push([ndAll[i]]);
  else runs[runs.length - 1].push(ndAll[i]);
}
for (const run of runs) {
  for (let off = 0; off + 10 <= run.length; off += 10) {
    const s = run.slice(off, off + 10).map((c) => String.fromCodePoint(c)).join('');
    add(s);
    add('-' + s);
    add(' ' + s + ' ');
    add(s.slice(0, 1) + s.slice(1));   // no-op, keeps variety
    add(String.fromCodePoint(run[off]) + String.fromCodePoint(run[off + 1]));
  }
  // whole run in one go, plus first/last
  add(run.map((c) => String.fromCodePoint(c)).join(''));
}

// ------------------------------------------------ mixed script digit strings
const zeros = runs.filter((r) => r.length >= 10).map((r) => r[0]);
for (let i = 0; i < zeros.length; i++) {
  const a = String.fromCodePoint(zeros[i] + 1);
  const b = String.fromCodePoint(zeros[(i + 1) % zeros.length] + 2);
  add(a + b);
  add('1' + a + '2' + b + '3');
  add(a + '_' + b);
}
// popular scripts explicit
const scriptZero = {
  arabicIndic: 0x0660, extArabicIndic: 0x06f0, devanagari: 0x0966, bengali: 0x09e6,
  gurmukhi: 0x0a66, gujarati: 0x0ae6, oriya: 0x0b66, tamil: 0x0be6, telugu: 0x0c66,
  kannada: 0x0ce6, malayalam: 0x0d66, thai: 0x0e50, lao: 0x0ed0, tibetan: 0x0f20,
  myanmar: 0x1040, khmer: 0x17e0, mongolian: 0x1810, fullwidth: 0xff10,
  osmanya: 0x104a0, mathBold: 0x1d7ce, mathDouble: 0x1d7d8, mathSans: 0x1d7e2,
  mathSansBold: 0x1d7ec, mathMono: 0x1d7f6, adlam: 0x1e950, brahmi: 0x11066,
  nko: 0x07c0, vai: 0xa620, cham: 0xaa50, lepcha: 0x1c40, ol_chiki: 0x1c50,
  sundanese: 0x1bb0, saurashtra: 0xa8d0, kayahli: 0xa900, javanese: 0xa9d0,
  chakma: 0x11136, sora: 0x110f0, takri: 0x116c0, warang: 0x118e0,
};
for (const z of Object.values(scriptZero)) {
  for (let d = 0; d < 10; d++) add(String.fromCodePoint(z + d));
  add(String.fromCodePoint(z) + String.fromCodePoint(z + 1));      // "01"
  add(String.fromCodePoint(z + 1) + String.fromCodePoint(z));      // "10"
  add(String.fromCodePoint(z + 9) + String.fromCodePoint(z + 9));  // "99"
  add('-' + String.fromCodePoint(z + 4) + String.fromCodePoint(z + 2));
  add('+' + String.fromCodePoint(z + 7));
  add(' ' + String.fromCodePoint(z + 3) + ' ');
  add(String.fromCodePoint(z + 1) + '_' + String.fromCodePoint(z + 2));
  add('1' + String.fromCodePoint(z + 2) + '3');
  let big = '';
  for (let d = 0; d < 40; d++) big += String.fromCodePoint(z + ((d * 3) % 10));
  add(big);
}

// --------------------------------------------- digits with combining marks
const marks = ['̀', '́', '̈', 'ً', '़', '⃣', '️', '‍'];
for (const m of marks) {
  add('1' + m);
  add(m + '1');
  add('1' + m + '2');
  add('١' + m);
  add(m + '١');
  add('०' + m + '१');
}

// ------------------------------------------------------------- near-miss junk
const junk = [
  '', ' ', '1.0', '1.', '.1', '1e5', '1E5', '0x10', '0X10', '0b1', '0o7', '10L', '1l',
  'inf', 'nan', 'Infinity', 'None', 'True', 'False', '1,000', "1'000", '1 000',
  '½', '²', '¹', '⁵', '₃', 'Ⅻ', '〇', '十', '百', '一', '零',
  '④', '⑩', '⒈', '⓵', '🄀', '۝', '⁰',
  '፩', '፪', // Ethiopic digits (No)
  '〇',           // ideographic number zero (Nl)
  '\u{1f522}',        // input symbol for numbers
  '1�'.replace('�', ''), // (no NUL in argv)
  '＋42', '－42', '−42', '﹢42', '⁺42',   // fullwidth / unicode signs
  '42·', '·42',
  '१२३abc', 'abc१२३',
  '1２3', '１2３',
  '٤٢x', 'x٤٢',
  '‎42', '42‏',
  '−' + '5',
  '9'.repeat(50) + 'a',
  'a' + '9'.repeat(50),
  '9'.repeat(50) + '©',
  '©' + '9'.repeat(50),
  '9'.repeat(4400) + 'a',
  '😀',      // emoji (surrogate pair, well-formed)
  '4\u{1f600}2',
  '\u{10000}',
];
for (const j of junk) add(j);

// non-ASCII junk with truncating fold (TransformDecimalAndSpaceToASCII stops at
// the first non-decimal, non-space char >= 127)
for (const tail of ['_', '_1', ' ', '1', 'x', ' ', '١']) {
  add('1é' + tail);
  add('é' + tail);
  add('1_é' + tail);
}

// ---------------------------------------------- interaction with --a and --c
add('42', 'é', '1.5');
add('-9' + '9'.repeat(120), 'big', '-0.0');
add('0', '', 'inf');

writeFileSync('/tmp/diff/int-parse-cases.json', JSON.stringify(cases));
console.log('cases:', cases.length, 'Nd code points:', ndAll.length, 'runs:', runs.length);

